\uff1b\u4f59\u989d\u5fc5\u987b\u8db3\u591f\u652f\u4ed8\u8d4c\u6ce8\u3002"),scopa=c("\u6253\u51fa\u4e00\u5f20\u624b\u724c\u3002\u5982\u684c\u4e0a\u6709\u540c\u70b9\u724c\uff0c\u5fc5\u987b\u62ff\u53d6\uff1b\u5426\u5219\u62ff\u53d6\u70b9\u6570\u4e4b\u548c\u7b49\u4e8e\u6240\u51fa\u724c\u7684\u7ec4\u5408\u3002\u65e0\u6cd5\u62ff\u53d6\u65f6\u5c06\u6240\u51fa\u724c\u7559\u5728\u684c\u9762\u3002","\u9009\u4e2d\u624b\u724c\uff0c\u518d\u9009\u62e9\u7f16\u53f7\u6355\u83b7\u65b9\u6848\uff1b\u76f8\u5e94\u684c\u9762\u4f4d\u7f6e\u4f1a\u9ad8\u4eae\u3002\u6e05\u7a7a\u684c\u9762\u5f97\u4e00\u6b21 scopa\uff0c\u4f46\u4e00\u526f\u724c\u7684\u6700\u540e\u4e00\u6b21\u51fa\u724c\u4e0d\u8ba1\u6e05\u53f0\u5206\u3002","\u724c\u6570\u3001\u91d1\u5e01\u3001\u91d1\u5e01\u4e03\u3001primiera\u53ca\u6e05\u53f0\u8ba1\u5206\u3002\u4e24\u4e09\u4eba\u5404\u81ea\u6bd4\u8d5b\uff0c\u56db\u4eba\u6309\u5bf9\u9762\u642d\u6863\u3002\u4e0b\u4e00\u624b\u4fdd\u7559\u6bd4\u5206\uff0c\u8fbe\u5230\u76ee\u6807\u540e\u7684\u65b0\u6bd4\u8d5b\u6e05\u96f6\u6bd4\u5206\u3002"),liar=c("\u9009\u724c\u80cc\u9762\u5f03\u51fa\uff0c\u5e76\u58f0\u660e\u70b9\u6570\uff1b\u5141\u8bb8\u8bc8\u552c\u3002\u58f0\u660e\u70b9\u6570\u4e00\u76f4\u4fdd\u6301\u5230\u6709\u4eba\u8d28\u7591\uff0c\u8bf7\u9075\u5b88\u663e\u793a\u7684\u724c\u6570\u4e0a\u9650\u3002","\u56de\u5e94\u65f6\u53ef\u8d28\u7591\u6700\u8fd1\u58f0\u660e\uff0c\u6216\u8fc7\u724c\u653e\u5f03\u8d28\u7591\uff1b\u8fd9\u91cc\u8fc7\u724c\u4e0d\u80fd\u8df3\u8fc7\u51fa\u724c\u56de\u5408\u3002\u8bc8\u552c\u88ab\u63ed\u7a7f\u65f6\u58f0\u660e\u8005\u6536\u8d70\u6574\u5806\uff0c\u5426\u5219\u8d28\u7591\u8005\u6536\u8d70\u3002\u53ea\u63ed\u793a\u6700\u8fd1\u58f0\u660e\u7684\u4e00\u7ec4\u724c\u3002","\u6253\u51fa\u6700\u540e\u7684\u724c\u540e\uff0c\u5fc5\u987b\u901a\u8fc7\u56de\u5e94\u9636\u6bb5\u624d\u80fd\u83b7\u80dc\u3002\u4e0b\u4e00\u526f\u91cd\u65b0\u6d17\u914d\u7f6e\u7684\u724c\u7ec4\u5e76\u8f6e\u6362\u53d1\u724c\u8005\uff0c\u4fdd\u7559\u539f\u73a9\u5bb6\u3002")))
